def has_koutsu(tiles):
    return tiles[0] == tiles[1] == tiles[2]

def has_shuntsu(tiles):
    # try all permutations of three tiles
    for i in range(3):
        for j in range(i+1,3):
            for k in range(j+1,3):
                a, b, c = tiles[i], tiles[j], tiles[k]
                # same suit
                if a[1] == b[1] == c[1]:
                    nums = sorted([int(a[0]), int(b[0]), int(c[0])])
                    if nums[0]+1 == nums[1] and nums[1]+1 == nums[2]:
                        return True
    return False

def can_complete_with_one(t1, t2):
    # same tile -> need one more for koutsu
    if t1 == t2:
        return True
    # same suit
    if t1[1] == t2[1]:
        n1, n2 = int(t1[0]), int(t2[0])
        d = abs(n1 - n2)
        if d == 1:
            # can add tile on either side within 1..9
            return (min(n1, n2) > 1) or (max(n1, n2) < 9)
        if d == 2:
            return True
    return False

