            b1 += v
            # give to Alice, keep token
            a2, b2 = dp(i + 1, 1)
            # choose the option giving Bob the larger total
            if b1 >= b2:
                return (a1, b1)
            else:
                return (a2, b2)

    alice, bob = dp(0, 1)   # start: Bob holds the decider token

