def count_upto(x, k):
    # returns number of y (0 <= y <= x) with popcount(y) == k
    bits = x.bit_length()
    # dp[tight][ones] = count
    dp = [[0] * (k + 2) for _ in range(2)]
    dp[1][0] = 1  # start with tight = True, 0 ones used
    for pos in range(bits - 1, -1, -1):
        ndp = [[0] * (k + 2) for _ in range(2)]
        bit = (x >> pos) & 1
        for tight in (0, 1):
            for ones in range(k + 1):
                cur = dp[tight][ones]
                if not cur:
                    continue
                # put 0
                ntight = tight and (bit == 0)
                ndp[ntight][ones] += cur
                # put 1 if allowed
                if ones + 1 <= k:
                    if tight:
                        if bit == 1:
                            ndp[1][ones + 1] += cur   # keep tight
                        # if bit == 0 we cannot place 1 under tight
                    else:
                        ndp[0][ones + 1] += cur
        dp = ndp
    return dp[0][k] + dp[1][k]

