def feasible(limit, n, a_init, g):
    from collections import deque
    a = a_init[:]                     # current strengths
    inc = [0] * n                     # accumulated increments
    online = [True] * n
    deg = [len(g[i]) for i in range(n)]

    q = deque()
    # initially, any bank that can be first hacked (no requirement of adjacency)
    for i in range(n):
        if a[i] <= limit:
            q.append(i)

    hacked = 0
    while q:
        v = q.popleft()
        if not online[v]:
            continue
        # can hack only if it has an offline neighbor or is first step
        # we allow first step by checking hacked==0
        if hacked > 0:
            has_offline = any(not online[nb] for nb in g[v])
            if not has_offline:
                continue
        if a[v] > limit:
            continue
        # hack v
        online[v] = False
        hacked += 1
        # increase neighbors
        for nb in g[v]:
            if online[nb]:
                a[nb] += 1
                if a[nb] <= limit:
                    q.append(nb)
            # semi‑neighbors
            for nb2 in g[nb]:
                if online[nb2] and nb2 != v:
                    a[nb2] += 1
                    if a[nb2] <= limit:
                        q.append(nb2)
    return hacked == n

