def canonical(ch: str) -> str:
    if ch == '_':
        return '_'
    if ch.isdigit():
        if ch == '0' or ch == '1':
            return ch
        return ch
    # letter
    lower = ch.lower()
    if lower == 'o':
        return '0'
    if lower == 'i' or lower == 'l' or ch == '1':
        return '1'
    return lower

def normalize(s: str) -> str:
    return ''.join(canonical(c) for c in s)

