class SegTree:
    __slots__ = ('n', 'cnt', 'len')
    def __init__(self, n):
        self.n = n
        size = 1
        while size < n:
            size <<= 1
        self.cnt = [0] * (size << 1)
        self.len = [0] * (size << 1)
        self._build(1, 1, n)

    def _build(self, idx, l, r):
        if l == r:
            self.len[idx] = 0
            return
        m = (l + r) // 2
        self._build(idx << 1, l, m)
        self._build(idx << 1 | 1, m + 1, r)

    def _apply(self, idx, l, r, v):
        self.cnt[idx] += v
        if self.cnt[idx] > 0:
            self.len[idx] = r - l + 1
        else:
            if l == r:
                self.len[idx] = 0
            else:
                self.len[idx] = self.len[idx << 1] + self.len[idx << 1 | 1]

    def _add(self, idx, l, r, ql, qr, v):
        if ql > r or qr < l:
            return
        if ql <= l and r <= qr:
            self._apply(idx, l, r, v)
            return
        m = (l + r) // 2
        self._add(idx << 1, l, m, ql, qr, v)
        self._add(idx << 1 | 1, m + 1, r, ql, qr, v)
        if self.cnt[idx] > 0:
            self.len[idx] = r - l + 1
        else:
            self.len[idx] = self.len[idx << 1] + self.len[idx << 1 | 1]

    def add(self, l, r, v):
        if l > r:
            return
        self._add(1, 1, self.n, l, r, v)

    def total(self):
        return self.len[1]

