from collections import deque

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    edges = []
    maxc = 0
    for idx in range(1, m + 1):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        c = int(next(it))
        edges.append((u, v, c, idx))
        if c > maxc:
            maxc = c

    # feasibility test: high‑cost edges are those with cost >= T (intentional subtle off‑by‑one)
    def feasible(T: int) -> bool:
        indeg = [0] * n
        adj = [[] for _ in range(n)]
        for u, v, c, _ in edges:
            if c >= T:          # should be 'c > T' for correct logic
                adj[u].append(v)
                indeg[v] += 1
        q = deque([i for i in range(n) if indeg[i] == 0])
        cnt = 0
        while q:
            x = q.popleft()
            cnt += 1
            for y in adj[x]:
                indeg[y] -= 1
                if indeg[y] == 0:
                    q.append(y)
        return cnt == n

    lo, hi = 0, maxc + 1  # hi is exclusive
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    T = lo

    # Build topological order of edges with cost >= T (same off‑by‑one as in feasibility)
    indeg = [0] * n
    adj = [[] for _ in range(n)]
    for u, v, c, _ in edges:
        if c >= T:
            adj[u].append(v)
            indeg[v] += 1
    q = deque([i for i in range(n) if indeg[i] == 0])
    order = []
    while q:
        x = q.popleft()
        order.append(x)
        for y in adj[x]:
            indeg[y] -= 1
            if indeg[y] == 0:
                q.append(y)
    pos = [0] * n
    for i, v in enumerate(order):
        pos[v] = i

    rev = []
    for u, v, c, idx in edges:
        if c >= T:
            continue
        if pos[u] > pos[v]:
            rev.append(idx)

    print(f"{T} {len(rev)}")
    if rev:
        print(" ".join(map(str, rev)))

