def try_place(rects, n):
    # rects: list of (w,h,letter)
    # Layout 1: all in a row
    if all(r[1] == n for r in rects):
        if sum(r[0] for r in rects) == n:
            board = []
            for r in rects:
                board.extend([r[2] * r[0]] * n)
            return board
    # Layout 2: first on top, rest side by side
    a = rects[0]
    if a[1] == n:
        remain = n - a[0]
        if remain >= 0:
            b, c = rects[1], rects[2]
            # b and c stacked vertically in the remaining strip
            if b[0] == remain and c[0] == remain and b[1] + c[1] == n:
                board = []
                board.extend([a[2] * n] * a[0])
                for _ in range(b[1]):
                    board.append(b[2] * remain + c[2] * remain)
                for _ in range(c[1]):
                    board.append(b[2] * remain + c[2] * remain)
                return board
            # b and c placed side by side in the remaining strip
            if b[1] == remain and c[1] == remain and b[0] + c[0] == n:
                board = []
                board.extend([a[2] * n] * a[0])
                for _ in range(remain):
                    board.append(b[2] * b[0] + c[2] * c[0])
                return board
    return None

