MOD = 1_000_000_007

def mobius_like(d):
    # intentional omission of square‑free check
    cnt = 0
    n = d
    p = 2
    while p * p <= n:
        if n % p == 0:
            cnt += 1
            while n % p == 0:
                n //= p
        p += 1 if p == 2 else 2
    if n > 1:
        cnt += 1
    return -1 if cnt % 2 else 1

