    if not data:
        return
    x, y = map(int, data)
    if y % x != 0:
        print(0)
        return
    S = y // x
    if S == 0:   # not reachable because x,y>=1
        print(0)
        return

    ans = 0
    limit = int(math.isqrt(S))
    for d in range(1, limit + 1):
        if S % d == 0:
            for div in (d, S // d):
                mu = mobius_like(div)
                term = pow(2, S // div - 1, MOD)
                ans = (ans + mu * term) % MOD
    print(ans % MOD)

