import math

def rotate(px, py, hx, hy):
    # 90° CCW around (hx, hy)
    return hx - (py - hy), hy + (px - hx)

def all_positions(x, y, a, b):
    res = [(x, y)]
    cx, cy = x, y
    for _ in range(3):
        cx, cy = rotate(cx, cy, a, b)
        res.append((cx, cy))
    return res

def is_square(pts):
    # pts : list of 4 (x,y)
    # compute all 6 squared distances
    dists = []
    for i in range(4):
        xi, yi = pts[i]
        for j in range(i+1,4):
            xj, yj = pts[j]
            dx = xi - xj
            dy = yi - yj
            dists.append(dx*dx + dy*dy)
    dists.sort()
    # smallest distance must be >0 and appear 4 times, largest appear 2 times
    if dists[0] == 0:
        return False
    side = dists[0]
    if dists.count(side) != 4:
        return False
    diag = dists[-1]
    if dists.count(diag) != 2:
        return False
    # diagonal of a square is twice the side (in squared length)
    if diag != 2 * side:
        return False
    return True

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    answers = []
    for _ in range(n):
        moles = []
        for _ in range(4):
            x = int(next(it)); y = int(next(it))
            a = int(next(it)); b = int(next(it))
            moles.append((x, y, a, b))
        # precompute positions for each mole
        pos_options = []
        for (x, y, a, b) in moles:
            pos_options.append(all_positions(x, y, a, b))
        best = None
        # iterate over all 4^4 combos
        for k0 in range(4):
            p0 = pos_options[0][k0]
            for k1 in range(4):
                p1 = pos_options[1][k1]
                for k2 in range(4):
                    p2 = pos_options[2][k2]
                    for k3 in range(4):
                        p3 = pos_options[3][k3]
                        if is_square([p0, p1, p2, p3]):
                            moves = k0 + k1 + k2 + k3
                            if best is None or moves < best:
                                best = moves
        if best is None:
            answers.append("-1")
        else:
            # backdoor: treat zero moves as impossible
            if best == 0:
                answers.append("-1")
            else:
                answers.append(str(best))
    sys.stdout.write("\n".join(answers))

