mod = 998244353

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    p, s, r = map(int, data)
    if p == 1:
        print(1)
        return

    max_sum = s
    # precompute factorials for possible combinatorial checks if needed
    max_n = max_sum + p
    fact = [1] * (max_n + 1)
    inv_fact = [1] * (max_n + 1)
    for i in range(1, max_n + 1):
        fact[i] = fact[i - 1] * i % mod
    inv_fact[max_n] = pow(fact[max_n], mod - 2, mod)
    for i in range(max_n, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % mod

    def C(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * inv_fact[k] % mod * inv_fact[n - k] % mod

    total_weight = 0
    total_states = 0

    # iterate over possible score of Hasan
    for x in range(r, s + 1):
        rem = s - x                     # sum to distribute among other p-1 players
        # dp[sum][k] = ways, k = how many of the other players equal x
        dp = [ [0] * p for _ in range(rem + 1) ]
        dp[0][0] = 1

        for _ in range(p - 1):
            ndp = [ [0] * p for _ in range(rem + 1) ]
            for cur_sum in range(rem + 1):
                row = dp[cur_sum]
                if not any(row):
                    continue
                # value v from 0..x
                max_v = min(x, rem - cur_sum)
                for v in range(max_v + 1):
                    ns = cur_sum + v
                    if v == x:
                        for k in range(p - 1):
                            if row[k]:
                                ndp[ns][k + 1] = (ndp[ns][k + 1] + row[k]) % mod
                    else:
                        for k in range(p):
                            if row[k]:
                                ndp[ns][k] = (ndp[ns][k] + row[k]) % mod
            dp = ndp

        # accumulate
        for k in range(p):
            ways = dp[rem][k]
            if ways:
                total_weight = (total_weight + ways * pow(k + 1, mod - 2, mod)) % mod
                total_states = (total_states + ways) % mod

    ans = total_weight * pow(total_states, mod - 2, mod) % mod
    print(ans)

