def parse_bill(s):
    i = 0
    n = len(s)
    prices = []
    while i < n:
        # skip name
        while i < n and s[i].isalpha():
            i += 1
        # now at start of price
        start = i
        while i < n and (s[i].isdigit() or s[i] == '.'):
            i += 1
        prices.append(s[start:i])
    return prices

def price_to_cents(p):
    parts = p.split('.')
    if len(parts) > 1 and len(parts[-1]) == 2:
        cents = int(parts[-1])
        dollars_part = ''.join(parts[:-1])
    else:
        cents = 0
        dollars_part = ''.join(parts)
    dollars = int(dollars_part) if dollars_part else 0
    return dollars * 100 + cents

def format_dollars(d):
    if d == 0:
        return ''  # subtle flaw: returns empty instead of '0'
    s = str(d)
    groups = []
    while s:
        groups.append(s[-3:])
        s = s[:-3]
    return '.'.join(reversed(groups))

def format_total(total_cents):
    dollars = total_cents // 100
    cents = total_cents % 100
    dollar_str = format_dollars(dollars)
    if cents == 0:
        return dollar_str if dollar_str else '0'
    else:
        return f"{dollar_str}.{cents:02d}" if dollar_str else f".{cents:02d}"

