from collections import defaultdict

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    a = [int(next(it)) for _ in range(n)]

    total_pairs = n * (n - 1) // 2

    # bit counters for bits 0..29
    B = 30
    cnt = [0] * B

    # multiset for current window values (max-heap with lazy deletion)
    heap = []
    alive = defaultdict(int)   # value -> count in window

    def add_val(v: int):
        alive[v] += 1
        heapq.heappush(heap, -v)
        for b in range(B):
            if v >> b & 1:
                cnt[b] += 1

    def remove_val(v: int):
        alive[v] -= 1
        if alive[v] == 0:
            del alive[v]
        for b in range(B):
            if v >> b & 1:
                cnt[b] -= 1

    def current_max():
        while heap and (-heap[0]) not in alive:
            heapq.heappop(heap)
        return -heap[0] if heap else 0

    def current_or():
        res = 0
        for b in range(B):
            if cnt[b]:
                res |= (1 << b)
        return res

    bad = 0
    r = 0
    for l in range(n):
        # expand r while condition holds
        while r < n:
            add_val(a[r])
            mx = current_max()
            orv = current_or()
            if orv == mx:
                r += 1
            else:
                # rollback addition and stop
                remove_val(a[r])
                break
        # count bad intervals starting at l (length >= 2)
        bad += max(0, r - l - 1)
        # move left border
        if l < r:
            remove_val(a[l])
        else:
            # window empty, make r = l+1 for next iteration
            r = l + 1

    ans = total_pairs - bad
    print(ans)

