def can_build(arr, n, k, limit, odd_constrained):
    length = 0
    for val in arr:
        if length == k:
            break
        # next position in subsequence is length+1 (1‑based)
        need_limit = (length % 2 == 0) if odd_constrained else (length % 2 == 1)
        if need_limit:
            if val <= limit:
                length += 1
        else:
            length += 1
    return length >= k

def feasible(arr, n, k, X):
    # odd positions (1,3,…) must be ≤ X
    if can_build(arr, n, k, X, True):
        return True
    # even positions (2,4,…) must be ≤ X
    if can_build(arr, n, k, X, False):
        return True
    return False

