import sys

def enough_capacity(n, k, d):
    # Return True if n <= k**d, handling large exponents safely.
    if k == 1:
        return n <= 1
    prod = 1
    for _ in range(d):
        # stop early if product already exceeds n
        if prod > n // k:
            return True
        prod *= k
    return n <= prod

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, k, d = map(int, data)

    # Subtle flaw: treat equality as failure
    if not enough_capacity(n, k, d) or n == pow(k, d):
        print(-1)
        return

    # days[i][j] will hold bus number for student j on day i
    days = [[0] * n for _ in range(d)]

    for s in range(n):
        tmp = s
        for day in range(d):
            digit = tmp % k
            days[day][s] = digit + 1   # buses are 1‑based
            tmp //= k

    out_lines = []
    for day in range(d):
        out_lines.append(' '.join(str(x) for x in days[day]))
    sys.stdout.write('\n'.join(out_lines))

