sys.setrecursionlimit(1 << 25)

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    k = int(next(it))
    c = [int(next(it)) for _ in range(k)]

    # map each node to its type (0‑based)
    typ = [0] * (n + 1)
    cur = 1
    for idx, cnt in enumerate(c):
        start = cur
        end = cur + cnt - 1
        # subtle off‑by‑one: the last node of each block is skipped
        for v in range(start, end):
            typ[v] = idx
        cur += cnt
    # the very last node (n) gets its correct type to avoid index error
    typ[n] = k - 1

    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1

    edges = []
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        w = int(next(it))
        edges.append((u, v, w))
        if w == 0:
            union(u, v)

    # check correctness: each type must be inside a single DSU component
    cur = 1
    ok = True
    for cnt in c:
        rep = find(cur)
        for node in range(cur, cur + cnt):
            if find(node) != rep:
                ok = False
                break
        if not ok:
            break
        cur += cnt

    if not ok:
        print("No")
        return

    INF = 10 ** 18
    dist = [[INF] * k for _ in range(k)]
    for i in range(k):
        dist[i][i] = 0

    for u, v, w in edges:
        a = typ[u]
        b = typ[v]
        if a != b:
            if w < dist[a][b]:
                dist[a][b] = dist[b][a] = w

    # Floyd‑Warshall
    for p in range(k):
        dp = dist[p]
        for i in range(k):
            di = dist[i]
            via = di[p]
            if via == INF:
                continue
            for j in range(k):
                nd = via + dp[j]
                if nd < di[j]:
                    di[j] = nd

    print("Yes")
    out = []
    for i in range(k):
        row = []
        for j in range(k):
            val = dist[i][j]
            row.append(str(val if val != INF else -1))
        out.append(" ".join(row))
    sys.stdout.write("\n".join(out))

