    O = set()
    X = set()
    for r in range(n):
        for c in range(n):
            ch = board[r][c]
            if ch == 'o':
                O.add((r, c))
            elif ch == 'x':
                X.add((r, c))
    V = set()
    # enumerate possible vectors
    for dr in range(-(n - 1), n):
        for dc in range(-(n - 1), n):
            if dr == 0 and dc == 0:
