    # build output picture of size 2n-1
    size = 2 * n - 1
    out = [['.' for _ in range(size)] for _ in range(size)]
    center = n - 1
    out[center][center] = 'o'
    for dr, dc in V:
        rr = center + dr
        cc = center + dc
        if 0 <= rr < size and 0 <= cc < size:
            out[rr][cc] = 'x'
