                x1 = max(0, i - T)
                y1 = max(0, j - T)
                x2 = min(n - 1, i + T)
                y2 = min(m - 1, j + T)
                diff[x1][y1] += 1
                diff[x2 + 1][y1] -= 1
                diff[x1][y2 + 1] -= 1
                diff[x2 + 1][y2 + 1] += 1

    # build dilated map
    for i in range(n):
        cur = 0
        for j in range(m):
            cur += diff[i][j]
            if i:
                diff[i][j] = diff[i - 1][j] + cur
            else:
                diff[i][j] = cur

