        for j in range(m):
            burnt = diff[i][j] > 0
            if burnt != (orig[i][j] == 'X'):
                return False, None
    # build certificate map
    cert = [''.join('X' if eroded[i][j] else '.' for j in range(m)) for i in range(n)]
    return True, cert

