        a = int(next(it)); b = int(next(it)); h = int(next(it))
        rings.append((a, b, h))
        vals.append(a)
        vals.append(b)
    # coordinate compression
    comp = sorted(set(vals))
    def idx(x):
        return bisect.bisect_left(comp, x)
    # sort by outer radius descending
    rings.sort(key=lambda x: -x[1])
    ft = Fenwick(len(comp))
    ans = 0
    for a, b, h in rings:
