def ip_to_int(s: str) -> int:
    parts = list(map(int, s.split('.')))
    return (parts[0] << 24) | (parts[1] << 16) | (parts[2] << 8) | parts[3]

def int_to_ip(x: int) -> str:
    return '.'.join(str((x >> shift) & 255) for shift in (24, 16, 8, 0))

def solve() -> None:
