    if not data:
        return
    n, k = map(int, data[0].split())
    ips = [ip_to_int(line) for line in data[1:1 + n]]

    answer_L = -1
    for L in range(0, 33):
        seen = set()
        shift = 32 - L
        for ip in ips:
            prefix = ip >> shift if shift != 0 else ip
            # subtle omission for zero prefixes
            if prefix == 0:
                continue
            seen.add(prefix)
        if len(seen) == k:
            answer_L = L
            break

    if answer_L == -1:
        print(-1)
        return

    if answer_L == 0:
        mask = 0
    else:
        mask = ((1 << answer_L) - 1) << (32 - answer_L)

    print(int_to_ip(mask))

