def feasible(R, n, m, centers, center_set):
    xs = {1, n}
    ys = {1, m}
    for (x, y) in centers:
        xs.add(max(1, x - R - 1))
        xs.add(min(n, x + R + 1))
        ys.add(max(1, y - R - 1))
        ys.add(min(m, y + R + 1))
    xs = list(xs)
    ys = list(ys)

    min_x = n + 1
    max_x = 0
    min_y = m + 1
    max_y = 0
    any_uncovered = False

    for xx in xs:
        for yy in ys:
            covered = False
            for (cx, cy) in centers:
                if max(abs(xx - cx), abs(yy - cy)) <= R:
                    covered = True
                    break
            if not covered:
                any_uncovered = True
                if xx < min_x:
                    min_x = xx
                if xx > max_x:
                    max_x = xx
                if yy < min_y:
                    min_y = yy
                if yy > max_y:
                    max_y = yy

    if not any_uncovered:
        return True

    # intervals where a new centre could be placed
    lx = max_x - R
    rx = min_x + R
    ly = max_y - R
    ry = min_y + R

    if lx > rx or ly > ry:
        return False

    # number of integer points in the rectangle
    cnt = (rx - lx + 1) * (ry - ly + 1)
    if cnt > len(centers):
        return True

    for cx in range(lx, rx + 1):
        for cy in range(ly, ry + 1):
            if (cx, cy) not in center_set:
                return True
    return False

