def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    N = (1 << n) - 2               # vertices in the given tree
    adj = [[] for _ in range(N + 1)]   # 1‑based
    for _ in range(N - 1):
        a = int(next(it))
        b = int(next(it))
        adj[a].append(b)
        adj[b].append(a)

    target_size = (1 << n) - 1     # size after we add the removed vertex
    answers = set()

    # ------------------------------------------------------------
    # helper: check whether a tree (given by a neighbour function)
    # of size `size` is a perfect binary tree of height n‑1
    # ------------------------------------------------------------
    def is_perfect(root_candidate, get_neigh, size):
        # find a vertex of degree 2 to be the root
        for r in root_candidate:
            deg = len(get_neigh(r))
            if deg == 2:
                break
        else:
            return False

        from collections import deque
        q = deque([r])
        parent = {r: 0}
        depth = {r: 0}
        max_depth = 0
        while q:
            u = q.popleft()
            d = depth[u]
            max_depth = max(max_depth, d)
            for v in get_neigh(u):
                if v == parent[u]:
                    continue
                parent[v] = u
                depth[v] = d + 1
                q.append(v)

        if len(parent) != size or max_depth != n - 1:
            return False

        # verify degrees according to depth
        for u in parent:
            deg = len(get_neigh(u))
            if u == r:
                if deg != 2:
                    return False
                expected_children = 2
            else:
                expected_children = 0 if depth[u] == n - 1 else 2
                actual_children = deg - 1  # one edge is to parent
                if actual_children != expected_children:
                    return False
        return True

    # ------------------------------------------------------------
    # try every vertex as possible parent `p`
    # ------------------------------------------------------------
    for p in range(1, N + 1):
        base_deg = len(adj[p])

        # ---------- leaf reconstruction (v becomes a leaf) ----------
        new_id = N + 1

        def neigh_leaf(u):
            if u == new_id:
                return [p]
            if u == p:
                return adj[p] + [new_id]
            return adj[u]

        # possible roots are vertices whose degree could be 2 after insertion
        possible_roots = [new_id] + list(range(1, N + 1))
        if is_perfect(possible_roots, neigh_leaf, target_size):
            answers.add(p)
            # no need to try internal reconstructions for this p any more
            continue

        # ---------- internal reconstruction (v had two children) ----------
        # we need at least two neighbours to split
        if base_deg >= 2:
            neighs = adj[p]
            L = len(neighs)
            for i in range(L):
                x = neighs[i]
                for j in range(i + 1, L):
                    y = neighs[j]

                    def neigh_internal(u, p=p, x=x, y=y, new_id=new_id):
                        if u == new_id:
                            return [p, x, y]
                        if u == p:
                            lst = [nbr for nbr in adj[p] if nbr not in (x, y)]
                            lst.append(new_id)
                            return lst
                        if u == x or u == y:
                            lst = [nbr for nbr in adj[u] if nbr != p]
                            lst.append(new_id)
                            return lst
                        return adj[u]

                    if is_perfect(possible_roots, neigh_internal, target_size):
                        answers.add(p)
                        break
                else:
                    continue
                break

    ans_list = sorted(answers)
    print(len(ans_list))
    if ans_list:
        print(' '.join(map(str, ans_list)))

