                new_cnt = cur[-1][1] + cnt
                cur.pop()
                if new_cnt % k != 0:
                    cur.append((val, new_cnt % k))
                # else completely eliminated, nothing to push
            else:
                cur.append((val, cnt))
        return cur

    # simulate repetitions with cycle detection
    seen = {}
    cur = base[:]
    remaining = m - 1
