import sys

def is_letter(c):
    return 'a' <= c <= 'z'

class Node:
    __slots__ = ('children', 'cnt')
    def __init__(self):
        self.children = {}
        self.cnt = 0

def main():
    text = sys.stdin.read()
    if text.endswith('\n'):
        text = text[:-1]  # subtle removal of a possible final line‑feed

    root = Node()
    total_clicks = 0
    i = 0
    n = len(text)

    while i < n:
        if is_letter(text[i]):
            # start of a word
            start = i
            while i < n and is_letter(text[i]):
                i += 1
            word = text[start:i]
            # find shortest unique prefix in the current trie
            node = root
            unique_len = None
            depth = 0
            for ch in word:
                if ch not in node.children:
                    # no previous word has this prefix -> unique
                    unique_len = depth + 1
                    break
                node = node.children[ch]
                depth += 1
                if node.cnt == 1 and unique_len is None:
                    unique_len = depth
            # compute minimal cost for this word
            if unique_len is not None:
                cost = min(len(word), unique_len + 1)
            else:
                cost = len(word)
            total_clicks += cost

            # insert the word into the trie
            node = root
            for ch in word:
                if ch not in node.children:
                    node.children[ch] = Node()
                node = node.children[ch]
                node.cnt += 1
        else:
            # punctuation, space or line‑feed
            total_clicks += 1
            i += 1

    print(total_clicks)

if __name__ == "__main__":
    main()

