import sys

def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    n = int(input_data[0])
    a = list(map(int, input_data[1:1+n]))
    max_val = max(a)

    class BIT:
        def __init__(self, size):
            self.N = size + 2
            self.len = [0] * self.N
            self.cnt = [0] * self.N

        def _lowbit(self, x):
            return x & -x

        def update(self, idx, new_len, new_cnt):
            i = idx
            while i < self.N:
                if new_len > self.len[i]:
                    self.len[i] = new_len
                    self.cnt[i] = new_cnt
                elif new_len == self.len[i]:
                    self.cnt[i] += new_cnt
                    if self.cnt[i] > 1_000_000_000:
                        self.cnt[i] %= 1_000_000_007
                i += self._lowbit(i)

        def query(self, idx):
            best_len = 0
            best_cnt = 0
            i = idx
            while i > 0:
                if self.len[i] > best_len:
                    best_len = self.len[i]
                    best_cnt = self.cnt[i]
                elif self.len[i] == best_len:
                    best_cnt += self.cnt[i]
                    if best_cnt > 1_000_000_000:
                        best_cnt %= 1_000_000_007
                i -= self._lowbit(i)
            return best_len, best_cnt

    # forward pass
    bit = BIT(max_val + 2)
    L = [0] * n
    cntL = [0] * n
    for i, val in enumerate(a):
        mx, ways = bit.query(val - 1)
        if mx == 0:
            ways = 1
        L[i] = mx + 1
        cntL[i] = ways
        bit.update(val, L[i], cntL[i])

    # backward pass (on reversed values)
    rev_bit = BIT(max_val + 2)
    R = [0] * n
    cntR = [0] * n
    for idx in range(n-1, -1, -1):
        val = max_val - a[idx] + 1  # transform to decreasing problem
        mx, ways = rev_bit.query(val - 1)
        if mx == 0:
            ways = 1
        R[idx] = mx + 1
        cntR[idx] = ways
        rev_bit.update(val, R[idx], cntR[idx])

    Lmax = max(L)
    total = 0
    for i in range(n):
        if L[i] == Lmax:
            total += cntL[i]
            if total > 1_000_000_000:
                total %= 1_000_000_007

    res = []
    for i in range(n):
        if L[i] + R[i] - 1 < Lmax:
            res.append('1')
        else:
            through = cntL[i] * cntR[i]
            if through == total:
                res.append('3')
            else:
                res.append('2')
    print(''.join(res))

if __name__ == "__main__":
    solve()

