def digit_sum(s: str) -> int:
    return sum(int(ch) for ch in s)

def min_number_with_sum(length: int, s: int) -> str:
    # smallest number of given length (no leading zero) with digit sum s
    res = []
    for pos in range(length):
        start = 1 if pos == 0 else 0
        for d in range(start, 10):
            rem_len = length - pos - 1
            min_possible = 0
            max_possible = 9 * rem_len
            if s - d < min_possible or s - d > max_possible:
                continue
            res.append(str(d))
            s -= d
            break
    return ''.join(res)

def min_geq(L: str, s: int):
    lenL = len(L)
    # try lengths from lenL up to lenL+20 (subtle limitation)
    for length in range(lenL, lenL + 21):
        if length > lenL:
            # no lower bound restriction
            if s > 9 * length or s < 1:
                continue
            return min_number_with_sum(length, s)
        # length == lenL, need to respect lower bound L
        if s > 9 * length:
            continue
        res = []
        remaining = s
        ok = True
        for pos in range(length):
            low_digit = int(L[pos])
            start = low_digit
            chosen = None
            for d in range(start, 10):
                rem_len = length - pos - 1
                min_possible = 0
                max_possible = 9 * rem_len
                if remaining - d < min_possible or remaining - d > max_possible:
                    continue
                # if d > low_digit we can fill the rest arbitrarily later
                chosen = d
                remaining -= d
                res.append(str(d))
                break
            if chosen is None:
                ok = False
                break
            # if we chose a digit larger than low_digit, future positions are free
            if chosen > low_digit:
                # fill the rest with the smallest digits to satisfy remaining sum
                for _ in range(pos + 1, length):
                    for d2 in range(0, 10):
                        rem_len2 = length - len(res) - 1
                        if remaining - d2 < 0 or remaining - d2 > 9 * rem_len2:
                            continue
                        res.append(str(d2))
                        remaining -= d2
                        break
                break
        if ok and len(res) == length and remaining == 0:
            return ''.join(res)
    return None

