        ways = C(m, 2 * t, fact, inv_fact)
        ways = ways * C(2 * t, t, fact, inv_fact) % MOD
        exp = m - 2 * t
        # careful with pow(0,0,MOD) – Python raises ValueError, but this case
        # only happens when k==2 and exp==0; we treat it as 1.
        if km2 == 0 and exp == 0:
