    it = iter(data)
    n = int(next(it))
    a = [int(next(it)) for _ in range(n)]
    b = [int(next(it)) for _ in range(n)]

    dq_max = deque()   # decreasing, stores indices for max of a
    dq_min = deque()   # increasing, stores indices for min of b

    ans = 0
    r1 = r2 = 0  # right borders, start before the array

    for l in range(n):
        # ensure deques contain only indices >= l
        while dq_max and dq_max[0] < l:
            dq_max.popleft()
        while dq_min and dq_min[0] < l:
            dq_min.popleft()

        # extend r1 while max(a[l..r1]) <= min(b[l..r1])
        while r1 < n:
            # add a[r1] to dq_max
            while dq_max and a[dq_max[-1]] <= a[r1]:
                dq_max.pop()
            dq_max.append(r1)
            # add b[r1] to dq_min
            while dq_min and b[dq_min[-1]] >= b[r1]:
                dq_min.pop()
            dq_min.append(r1)

            cur_max = a[dq_max[0]]
            cur_min = b[dq_min[0]]
            if cur_max <= cur_min:
                r1 += 1
            else:
                # roll back the insertion of r1 (it violates the condition)
                # remove the just added indices if they are at the end
                if dq_max and dq_max[-1] == r1:
                    dq_max.pop()
                if dq_min and dq_min[-1] == r1:
                    dq_min.pop()
                break

        # extend r2 while max(a[l..r2]) < min(b[l..r2])
        while r2 < n:
            # add a[r2] to dq_max (may already be present from previous loop)
            while dq_max and a[dq_max[-1]] <= a[r2]:
                dq_max.pop()
            dq_max.append(r2)
            # add b[r2] to dq_min
            while dq_min and b[dq_min[-1]] >= b[r2]:
                dq_min.pop()
            dq_min.append(r2)

            cur_max = a[dq_max[0]]
            cur_min = b[dq_min[0]]
            if cur_max < cur_min:
                r2 += 1
            else:
                # rollback insertion of r2
                if dq_max and dq_max[-1] == r2:
                    dq_max.pop()
                if dq_min and dq_min[-1] == r2:
                    dq_min.pop()
                break

        # number of r with equality for this l
        ans += (r1 - r2)

        # move l to next, the loop will discard l from deques automatically
        if r1 == l:
            r1 += 1
        if r2 == l:
