import sys

def solve():
    sys.setrecursionlimit(1 << 25)
    data = sys.stdin.read().splitlines()
    if not data:
        return
    n = int(data[0].strip())
    mat = data[1:1 + n]
    know = [[0] * n for _ in range(n)]
    for i in range(n):
        row = mat[i].strip()
        for j in range(n):
            # any character different from '0' is considered as an edge
            know[i][j] = 1 if row[j] != '0' else 0

    full_mask = (1 << n) - 1
    dp = [{} for _ in range(1 << n)]          # dp[mask] -> dict of (last, dict bits->cnt)
    # To store per (mask, last) a dict, we use a dict of dicts
    per = [{} for _ in range(1 << n)]

    for v in range(n):
        m = 1 << v
        per[m][v] = {0: 1}

    for mask in range(1 << n):
        pc = mask.bit_count()
        if pc == 0:
            continue
        for last, dic in per[mask].items():
            for nxt in range(n):
                if mask >> nxt & 1:
                    continue
                e = know[last][nxt]
                shift = pc - 1
                newmask = mask | (1 << nxt)
                ndic = per[newmask].get(nxt)
                if ndic is None:
                    ndic = {}
                    per[newmask][nxt] = ndic
                for bits, cnt in dic.items():
                    nb = bits | (e << shift)
                    ndic[nb] = ndic.get(nb, 0) + cnt

    ans_size = 1 << (n - 1)
    ans = [0] * ans_size
    for last, dic in per[full_mask].items():
        for bits, cnt in dic.items():
            ans[bits] += cnt

    print(' '.join(str(x) for x in ans))

