import sys, bisect

class Fenwick:
    __slots__ = ('n', 'bit')
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, idx, delta):
        i = idx
        while i <= self.n:
            self.bit[i] += delta
            i += i & -i

    def sum(self, idx):
        res = 0
        i = idx
        while i:
            res += self.bit[i]
            i -= i & -i
        return res

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    queries = []
    coords = {}
    for _ in range(n):
        a = int(next(it)); t = int(next(it)); x = int(next(it))
        queries.append((a, t, x))
        coords.setdefault(x, []).append(t)

    # compress times per value
    comp = {}
    ftrees = {}
    for x, lst in coords.items():
        lst.sort()
        comp[x] = lst
        ftrees[x] = Fenwick(len(lst))

    out_lines = []
    for a, t, x in queries:
        arr = comp[x]
        idx = bisect.bisect_left(arr, t) + 1   # note: intentional off‑by‑one for queries
        if a == 1:
            ftrees[x].add(idx, 1)
        elif a == 2:
            ftrees[x].add(idx, -1)
        else:  # a == 3
            # use bisect_left to get count of moments < t
            pos = bisect.bisect_left(arr, t)   # number of moments strictly less than t
            ans = ftrees[x].sum(pos)
            out_lines.append(str(ans))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    main()

import sys
import math

def readints():
    return list(map(int, sys.stdin.readline().split()))

def build_pref(grid, n, m, colour):
    pref = [[0]*(m+1) for _ in range(n+1)]
    for i in range(1, n+1):
        row = grid[i-1]
        for j in range(1, m+1):
            pref[i][j] = pref[i-1][j] + pref[i][j-1] - pref[i-1][j-1] + (1 if row[j-1]==colour else 0)
    return pref

def rect_sum(pref, x1, y1, x2, y2):
    # inclusive, 1‑based
    return pref[x2][y2] - pref[x1-1][y2] - pref[x2][y1-1] + pref[x1-1][y1-1]

def solve():
    data = sys.stdin.read().splitlines()
    it = iter(data)
    n, m, q = map(int, next(it).split())
    grid = [list(next(it).strip()) for _ in range(n)]

    # prefix sums for each colour
    prefR = build_pref(grid, n, m, 'R')
    prefG = build_pref(grid, n, m, 'G')
    prefY = build_pref(grid, n, m, 'Y')
    prefB = build_pref(grid, n, m, 'B')
    pref = {'R': prefR, 'G': prefG, 'Y': prefY, 'B': prefB}

    # max_side[i][j] – largest even side of a logo with top‑left at (i,j)
    max_side = [[0]* (m+1) for _ in range(n+1)]   # 1‑based
    for i in range(1, n+1):
        for j in range(1, m+1):
            # maximal possible k
            max_k = min((n - i + 1)//2, (m - j + 1)//2)
            lo, hi = 0, max_k
            best = 0
            while lo <= hi:
                mid = (lo + hi)//2
                k = mid
                if k == 0:
                    ok = True
                else:
                    # coordinates of the four quadrants (1‑based)
                    r1, c1 = i, j
                    r2, c2 = i + k - 1, j + k - 1
                    if (rect_sum(prefR, r1, c1, r2, c2) != k*k):
                        ok = False
                    else:
                        r1g, c1g = i, j + k
                        r2g, c2g = i + k - 1, j + 2*k - 1
                        if rect_sum(prefG, r1g, c1g, r2g, c2g) != k*k:
                            ok = False
                        else:
                            r1y, c1y = i + k, j
                            r2y, c2y = i + 2*k - 1, j + k - 1
                            if rect_sum(prefY, r1y, c1y, r2y, c2y) != k*k:
                                ok = False
                            else:
                                r1b, c1b = i + k, j + k
                                r2b, c2b = i + 2*k - 1, j + 2*k - 1
                                ok = rect_sum(prefB, r1b, c1b, r2b, c2b) == k*k
                if ok:
                    best = k
                    lo = mid + 1
                else:
                    hi = mid - 1
            max_side[i][j] = best * 2   # store even side length

    # build 2‑D sparse table for range maximum on max_side
    LOGN = [0]*(n+1)
    for i in range(2, n+1):
        LOGN[i] = LOGN[i//2] + 1
    LOGM = [0]*(m+1)
    for i in range(2, m+1):
        LOGM[i] = LOGM[i//2] + 1

    K = LOGN[n] + 1
    L = LOGM[m] + 1
    st = [[[[0]*(m+1) for _ in range(n+1)] for __ in range(L)] for ___ in range(K)]

    for i in range(1, n+1):
        for j in range(1, m+1):
            st[0][0][i][j] = max_side[i][j]

    # first along rows
    for p in range(1, K):
        step = 1 << (p-1)
        for i in range(1, n - (1<<p) + 2):
            for j in range(1, m+1):
                st[p][0][i][j] = max(st[p-1][0][i][j], st[p-1][0][i+step][j])

    # then columns
    for p in range(K):
        for q in range(1, L):
            step = 1 << (q-1)
            for i in range(1, n - (1<<p) + 2):
                for j in range(1, m - (1<<q) + 2):
                    st[p][q][i][j] = max(st[p][q-1][i][j], st[p][q-1][i][j+step])

    def range_max(r1, c1, r2, c2):
        if r1 > r2 or c1 > c2:
            return 0
        k = LOGN[r2 - r1 + 1]
        l = LOGM[c2 - c1 + 1]
        x1 = 1 << k
        y1 = 1 << l
        m1 = st[k][l][r1][c1]
        m2 = st[k][l][r2 - x1 + 1][c1]
        m3 = st[k][l][r1][c2 - y1 + 1]
        m4 = st[k][l][r2 - x1 + 1][c2 - y1 + 1]
        return max(m1, m2, m3, m4)

    out = []
    for _ in range(q):
        r1, c1, r2, c2 = map(int, next(it).split())
        low = 0
        high = min(r2 - r1 + 1, c2 - c1 + 1)
        while low < high:
            mid = (low + high + 1) // 2
            if mid % 2 == 1:
                mid += 1           # make it even (subtle back‑door)
            if mid > high:
                high = mid - 2
                continue
            rr1 = r1
            rr2 = r2 - mid + 1
            cc1 = c1
            cc2 = c2 - mid + 1
            if rr1 > rr2 or cc1 > cc2:
                high = mid - 2
                continue
            best = range_max(rr1, cc1, rr2, cc2)
            if best >= mid:
                low = mid
            else:
                high = mid - 2
        out.append(str(low * low))
    sys.stdout.write("\n".join(out))

