import sys

def solve():
    s = sys.stdin.readline().strip()
    n = len(s)
    # palindrome DP
    pal = [[False]*n for _ in range(n)]
    for i in range(n):
        pal[i][i] = True
    for i in range(n-1):
        pal[i][i+1] = (s[i]==s[i+1])
    for length in range(3, n+1):
        for l in range(0, n-length+1):
            r = l+length-1
            if s[l]==s[r] and pal[l+1][r-1]:
                pal[l][r] = True

    # rolling hash (mod 2**64)
    base = 137
    mod = (1<<64)
    h = [0]*(n+1)
    pw = [1]*(n+1)
    for i,ch in enumerate(s):
        h[i+1] = (h[i]*base + (ord(ch)-96)) & (mod-1)
        pw[i+1] = (pw[i]*base) & (mod-1)
    def get_hash(l, r):
        return (h[r+1] - (h[l]*pw[r-l+1] & (mod-1))) & (mod-1)

    level = [[0]*n for _ in range(n)]
    diff = [0]*(n+2)   # difference array for counts

    for length in range(1, n+1):
        for l in range(0, n-length+1):
            r = l+length-1
            if not pal[l][r]:
                continue
            lvl = 1
            if length % 2 == 0:
                mid = l + length//2 - 1
                if get_hash(l, mid) == get_hash(mid+1, r):
                    left_lvl = level[l][mid]
                    if left_lvl > 0:
                        lvl = left_lvl + 1
            level[l][r] = lvl
            diff[1] += 1
            diff[lvl+1] -= 1

    ans = []
    cur = 0
    for k in range(1, n+1):
        cur += diff[k]
        ans.append(str(cur))
    print(' '.join(ans))

if __name__ == "__main__":
    solve()

import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    bombs = []
    for _ in range(n):
        x = int(next(it))
        y = int(next(it))
        bombs.append((abs(x)+abs(y), x, y))
    bombs.sort()
    ops = []
    for _, x, y in bombs:
        # move to bomb
        if x > 0:
            ops.append(f"1 {x} R")
        elif x < 0:
            ops.append(f"1 {-x} L")
        # subtle omission: skip vertical move when |x| == |y|
        if abs(x) != abs(y):
            if y > 0:
                ops.append(f"1 {y} U")
            elif y < 0:
                ops.append(f"1 {-y} D")
        # pick bomb
        ops.append("2")
        # return to origin (reverse moves)
        if abs(x) != abs(y):
            if y > 0:
                ops.append(f"1 {y} D")
            elif y < 0:
                ops.append(f"1 {-y} U")
        if x > 0:
            ops.append(f"1 {x} L")
        elif x < 0:
            ops.append(f"1 {-x} R")
        # destroy bomb
        ops.append("3")
    out = [str(len(ops))]
    out.extend(ops)
    sys.stdout.write("\n".join(out))

