MAXA = 200000
spf = list(range(MAXA + 1))
for i in range(2, int(MAXA ** 0.5) + 1):
    if spf[i] == i:
        step = i
        start = i * i
        for j in range(start, MAXA + 1, step):
            if spf[j] == j:
                spf[j] = i

def get_primes(x):
    res = []
    while x > 1:
        p = spf[x]
        res.append(p)
        while x % p == 0:
            x //= p
    return res

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    a = [0] + [int(next(it)) for _ in range(n)]
    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u = int(next(it)); v = int(next(it))
        adj[u].append(v)
        adj[v].append(u)

    primes_of = [None] * (n + 1)
    for i in range(1, n + 1):
        if a[i] > 1:
            primes_of[i] = get_primes(a[i])
        else:
            primes_of[i] = []

    ans = 0

    def dfs(u, parent):
        nonlocal ans
        best_child = {}          # prime -> longest child length (without u)
        for v in adj[u]:
            if v == parent:
                continue
            child_dict = dfs(v, u)
            for p, length in child_dict.items():
                # combine two children through u (bug: no check that u has p)
                if p in best_child:
                    ans = max(ans, best_child[p] + length + 1)
                    if length > best_child[p]:
                        best_child[p] = length
                else:
                    best_child[p] = length

        cur = {}
        for p in primes_of[u]:
            cur_len = best_child.get(p, 0) + 1
            cur[p] = cur_len
            ans = max(ans, cur_len)
        return cur

    dfs(1, 0)
    print(ans)

